import 'package:flutter/material.dart';
import '../services/api.dart';
import '../widgets/figma.dart';
class ChatScreen extends StatefulWidget{final Map<String,dynamic> teacher; const ChatScreen({super.key, required this.teacher}); @override State<ChatScreen> createState()=>_ChatScreenState();}
class _ChatScreenState extends State<ChatScreen>{final api=const LarniaApi(); final q=TextEditingController(); String answer='Tu sa zobrazí odpoveď po odoslaní otázky.'; bool loading=false; Future<void> send()async{if(q.text.trim().isEmpty)return; setState(()=>loading=true); try{final r=await api.post('/api/chat', {'teacherId':widget.teacher['id'], 'question':q.text.trim()}); setState(()=>answer=r['answer']??'');}catch(e){setState(()=>answer='Chyba: $e');} finally{setState(()=>loading=false);}}
@override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.white, body:Padding(padding: const EdgeInsets.fromLTRB(45,80,45,35), child:Column(crossAxisAlignment:CrossAxisAlignment.start, children:[const LarniaHeader(title:'Chat', subtitle:'Napíš otázku pre AI učiteľa.'), const SizedBox(height:15), Container(width:70,height:30, alignment:Alignment.center, decoration:BoxDecoration(color: const Color(0xFFE5F8FA), borderRadius:BorderRadius.circular(15)), child: const Text('Online', style: TextStyle(color:blue, fontSize:13, fontWeight:FontWeight.w600))), const SizedBox(height:35), Expanded(child:FigmaCard(width:934,height:235,padding:const EdgeInsets.all(30), child:Column(crossAxisAlignment:CrossAxisAlignment.start, children:[const Text('AI učiteľ', style: TextStyle(color:blue,fontSize:24,fontWeight:FontWeight.w600)), const SizedBox(height:25), Text(answer, style: const TextStyle(color:blue,fontSize:16))]))), const SizedBox(height:40), Container(height:56, decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(12), boxShadow: const [BoxShadow(color:Color(0x26000000), offset:Offset(5,12), blurRadius:24)]), child:Row(children:[Expanded(child:TextField(controller:q, decoration: const InputDecoration(hintText:'Napíš otázku...', border:InputBorder.none, contentPadding:EdgeInsets.symmetric(horizontal:20)))), InkWell(onTap:loading?null:send, child:Container(width:42,height:42,margin: const EdgeInsets.only(right:12), alignment:Alignment.center, decoration:BoxDecoration(color:cyan,borderRadius:BorderRadius.circular(12)), child: loading? const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white)) : const Text('→', style: TextStyle(color:Colors.white,fontSize:26))))]))])));}
